/// @brief Enumeration for autofill function error.
///
/// @since_tizen 5.5
abstract class autofill_error_e {
  /// < Successful
  static const int AUTOFILL_ERROR_NONE = 0;

  /// < Invalid parameter
  static const int AUTOFILL_ERROR_INVALID_PARAMETER = -22;

  /// < Permission denied
  static const int AUTOFILL_ERROR_PERMISSION_DENIED = -13;

  /// < Not initialized
  static const int AUTOFILL_ERROR_NOT_INITIALIZED = -50397183;

  /// < Operation failed
  static const int AUTOFILL_ERROR_OPERATION_FAILED = -50397182;

  /// < Out of memory
  static const int AUTOFILL_ERROR_OUT_OF_MEMORY = -12;

  /// < Authentication failed
  static const int AUTOFILL_ERROR_AUTHENTICATION_FAILED = -50397181;

  /// < Failed to save autofill data
  static const int AUTOFILL_ERROR_COMMIT_FAILED = -50397180;

  /// < Failed to response fill request
  static const int AUTOFILL_ERROR_FILL_RESPONSE_FAILED = -50397179;

  /// < Unable to connect to Autofill Service
  static const int AUTOFILL_ERROR_SERVICE_NOT_CONNECTED = -50397178;

  /// < Autofill Service is not allowed
  static const int AUTOFILL_ERROR_SERVICE_NOT_ALLOWED = -50397177;

  /// < Autofill Service is not activated
  static const int AUTOFILL_ERROR_SERVICE_NOT_ACTIVATED = -50397176;

  /// < Could not find saved values
  static const int AUTOFILL_ERROR_SAVED_VALUES_NOT_FOUND = -50397175;
}
